/// <summary>
/// Example GUPPricingAttribute of table <c>InventDim</c> field InventSerialId.
/// </summary>
/// [GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::Product, GUPPricingAttributeSourceLevel::Line)]
internal class GUPPricingAttributeInventDimInventSerialId_Product extends GUPPricingAttributeInventDim_Product implements GUPIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(InventDim, InventSerialId);
}

public Set getAllowedValues()
{
    var ret = new Set(Types::String);
    InventDim inventDim;
    while select InventSerialId from inventDim
        group by InventSerialId
    {
        ret.add(inventDim.InventSerialId);
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(InventDim, InventSerialId));
    qbr.value(queryValue(_value));
}
